/*
#root.root {--toolbar-el-overlay-selected-border: transparent;}
#root.root {--frame-el-overlay-selected-border: transparent;}
*/

#root.root {--tabs-font: 0.8775rem SF Pro Text;}
#root.root {--notification-border-radius: 6px;}

#root.root {--tabs-inner-gap: 5px;}
#root.root {--tabs-color-layer-opacity: 0.1;}

#root{
	--bgnotif: light-dark(#f8f8f8, #1e1e1e);
}

#root {
  -moz-osx-font-smoothing: always;
}

#root[data-frame-color-scheme="light"] .Tab[data-colorized="true"] {
--tabs-activated-shadow: inset 0 0 0 1px rgba(0,0,0,0.3), 0 1px 3px -1px rgba(0,0,0,0.1) !important;
}





/*mica gradient  

