#root.root {--tabs-indent: 18px;}
#root.root {--nav-btn-margin: 2px;}
/* Control how much pinned tabs column you want below, width of the pinned tabs will be automatically resized depend on it. */
#root.root {--tabs-pinned-width: calc( (96vw - (var(--tabs-margin)*var(--pinned-tabs-col))) / var(--pinned-tabs-col));}
#root.root {--tabs-pinned-height: 45px;}

.NavigationBar .nav-item .audio {
  display: none;
}

.NavigationBar .nav-item .icon{
	opacity: .7;
}

.Tab .exp {opacity: 0}
.Tab .child-count{display:none;}
/* PINNED TABS */

.Tab[data-pin="true"] .body {
/*   box-shadow: 0px 2px 1px #00000000; */
  color: #ffffff60;

}

.Tab[data-pin="true"][data-active="true"] {
  border-radius: var(--general-border-radius);
}

.Tab[data-discarded="true"] > .body > .fav {
  opacity: .5;
	filter: grayscale(1);
}

#root .TabsPanel .PinnedTabsBar {
  display: flex;
  flex-wrap: wrap;
  margin: 0;
  padding: 0;
}

.PinnedTabsBar .tab-wrapper {
  flex-grow: 1;
  min-width: 45px;
  --tabs-pinned-width: auto;
}


#root.root{--separator-color: color-mix(
      in srgb,
      var(--frame-fg) 20%,
      transparent
    ) !important;}





/* SEPARATOR */

#root .top-shadow,
#root .bottom-shadow{
	width: calc(100% - var(--tabs-margin) * 2.3) !important;
  inset-inline: 8px !important;
  border:  1px solid light-dark(#00000014, #f2f2f214);
	height: 1px;
  box-shadow: none;
  border-radius: var(--general-border-radius);
}


#root .top-shadow {
  top: 0;
}

#root .bottom-shadow {
  bottom: 0;
}

.Tab .close-icon {
  height: 24px;
  width: 24px;
  top: calc(50% - 12px);
  left: calc(50% - 12px);
}


.Tab[data-pin="true"][data-active="false"] .body {
	box-shadow: 0px 2px 1px #00000000;
  background: light-dark(#0000000f, #ffffff0f);
  color: #ffffff20;
}
.Tab[data-pin="true"][data-active="true"]{
/*   background-color: var(--tabs-activated-bg)/*#8f8f8f78*/; */
  border-radius: var(--general-border-radius);
	box-shadow: var(--tabs-activated-shadow);
}

.Tab[data-pin="true"] .audio{
	background-color: transparent;
  box-shadow: none;
  top: calc(50% - 16px); /* Menyesuaikan posisi vertikal di tengah */
  right: calc(50% - 17px); 
	opacity: .8;
}

.Tab[data-pin="true"][data-audible="true"] .fav, .Tab[data-pin="true"][data-muted="true"] .fav, .Tab[data-pin="true"][data-paused="true"] .fav{
  z-index: 21;
  mask: radial-gradient(circle at calc(100% - 1px) calc(100% - 14px),rgba(0,0,0,.141),rgba(0,0,0,.141) 5px,#000 6px,#000);
}

/* GENERAL */
#root.root {--tabs-height: 38px;}
#root.root {--tabs-margin: 5px;}
#root.root {--tabs-close-btn-margin: 5px;}
#root.root {--general-border-radius: 10px;}
#root .popup-container {background-color: transparent;}
#root .hidden-panels-popup-layer:before {background-color: transparent;}

/* Smoothen masking for overflowed tab title.*/ 
.Tab .title {
	background: linear-gradient(90deg, var(--tabs-normal-fg) 80%, #f1f1f100 99%);
	background-clip: text;
	color: transparent;
}


.TabsPanel .new-tab-btn > svg, .TabsPanel .new-tab-btn > img {
  fill: var(--color, var(--frame-fg));
  opacity: 0.4;
}

/* NEW TAB BUTTON */
.TabsPanel .new-tab-btns{
	position: relative;
  padding-top: 0px;
}

.TabsPanel .new-tab-btn {
  height: var(--tabs-height);}

.TabsPanel .new-tab-btn {
  justify-content: left;
  padding-left: calc(var(--tabs-inner-gap));
  margin-left: calc(var(--tabs-margin)*0.6);
  margin-right: calc(var(--tabs-margin)*0.6);
  --ntb-btn-height: var(calc(var(--tabs-height) + var(--tabs-margin)));
}

.TabsPanel .new-tab-btn > svg, .TabsPanel .new-tab-btn > img {
  fill: transparent;
  background-color: var(--nav-btn-fg);
  opacity: .4;
  width: 17px;
  height: 17px;
  scale: 0.9;
  mask: url("data:image/svg+xml;base64,");
}

.TabsPanel .new-tab-btn:after {
  justify-content: left;
  content: "New Tab";
  font: var(--tabs-font);
  padding-left: calc(var(--tabs-inner-gap) + var(--tabs-margin) + 13px);
  color: var(--nav-btn-fg);  
  opacity: .3;
}

/* NAVBAR */

#root.root {--nav-btn-width: 25px;}
#root.root {--nav-btn-height: 25px;}

#root.root {--toolbar-bg: transparent;}

/* Moving Sidebery navigation bar to bottom, to mimic how Space works on Arc Browser. Make sure to choose Horizontal when activating the navigation bar. */
.NavigationBar {box-shadow: none;}
.top-horizontal-box {
  display: flex;
  order: 1; 
  margin-left: 5px;
  margin-right: 5px;
  margin-top: 3px;
}

.NavigationBar .nav-item {
	border-radius: calc(var(--general-border-radius) / 1.5);
}

/* Remove background color, border and shadow for active tab panel. */
.NavigationBar .nav-item[data-active="true"] {
  background-color: transparent;
  box-shadow: none;
}

/* Making non-active tabs (including bookmark panels) grayscale. */
.NavigationBar .nav-item[data-active="false"] .icon {
  fill: var(--nav-btn-fg);
  opacity: 40%;
  scale: 0.75;
}

/* Settings related to Hidden Panels icon and popup layer, adapting to the flipped navbar orientation. */
#hidden_panels_btn.nav-item .icon {
  transform: scaleY(-1);
  opacity: 40%;
  scale: 0.9;
}
.hidden-panels-popup-layer {
  transform: scaleY(-1);  
  margin-top: -15%;
  --toolbar-bg: var(--frame-bg);
}
.NavigationBar .hidden-panels-popup-content {
  transform: scaleY(-1);
}

/* Adjust 'add tabs panel' size & position. */
#root .PanelConfigPopup .popup {
  width: 80vw;
  margin-top: 15vh;
}

/* Replacing 'add tabs panel' button with Fluent plus icon to mimic Arc's 'new space' button. */
.NavigationBar #add_tp.nav-item .icon {
  fill: transparent;
  background-color: var(--nav-btn-fg);
	opacity: .6;
  width: 80%;
  height: 80%;
  mask: url("data:image/svg+xml;base64,");
}

/* Replacing 'history' panel with Fluent archive icon to mimic Arc's 'recently closed' button. 
.NavigationBar #navhistory.nav-item .icon {
  fill: transparent;
  background-color: var(--nav-btn-fg);
  display: flex;
  padding: auto;
	opacity: .5 ;
  width: 80%;
  height: 80%;
  mask: url("data:image/svg+xml;base64,");
}
*/
/* Replacing Sidebery 'settings' with Fluent settings icon to blend with Arc (Windows) aesthetic. */
.NavigationBar #settings.nav-item .icon {
  fill: transparent;
  background-color: var(--nav-btn-fg);
  width: 75%;
  height: 75%;
  mask: url("data:image/svg+xml;base64,")
}

/* New tab button styling. 
*/
   .TabsPanel .new-tab-btns {
		margin-top: calc(var(--tabs-margin)/4 -3);
    padding-top: var(--tabs-margin) !important;
      &::before {
        width: calc(100% - var(--tabs-margin) * 2.1) !important;
        inset-inline: 5.3px !important;
        top: 0 !important;

        box-shadow: none !important;
      }

}

#root .TabsPanel .new-tab-btns::before{
  border-top:  1px solid light-dark(#00000014, #f2f2f214);
  box-shadow: none;
	height: 1px
  border-radius: var(--general-border-radius);
}


.NavigationBar .nav-item[data-type="tabs"][data-active="false"] .icon #icon_man{
	display:none;
}

/**/
.NavigationBar .nav-item[data-type="tabs"][data-active="false"]:not(:has(.len)) .icon {
  scale: 0.32;
  fill: transparent;
  background-color: var(--nav-btn-fg);
  width: 77%;
  height: 77%;
  mask: url("data:image/svg+xml;base64,PHN2ZyBpZD0iY2lyY2xlIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAzMiAzMiI+PGNpcmNsZSBjeD0iMTYiIGN5PSIxNiIgcj0iMTUiPjwvY2lyY2xlPjwvc3ZnPg==");
}

.NavigationBar .nav-item[data-type="tabs"][data-active="false"] .len{
opacity: .5;
}

.NavigationBar .nav-item .audio {
  box-shadow: none;

}


.Tab{
   animation: new-tab-appear 0.3s cubic-bezier(0.4, 0.0, 0.2, 1) !important;
}



@keyframes new-tab-appear { 
  0% {
    opacity: 0;
    transform: translateY(-15px);
  }
  60% {
    opacity: 0.8  ;
    transform: translateY(4px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}
.Tab[data-parent="true"] .fav:hover img, .Tab[data-parent="true"][data-folded="true"] .fav img {
  opacity: 0;
}

.Tab[data-selected="true"] .body::before, .Tab[data-selected="true"]:hover .body::before, .Tab[data-selected="true"]:active .body::before {
  background-color: var(--frame-el-overlay-selected-bg);
  box-shadow: inset 0 0 0 2px var(--frame-el-overlay-selected-border);
}

.Tab:hover .body::before, .TabsPanel .new-tab-btn:hover::before,
.NavigationBar .nav-item:not([data-class="space"]):hover{
	transition: background 0.15s linear !important;
}



.Tab[data-pin="true"] .badge{ 
	display:none;
}


.Tab .audio-icon {
  fill: var(--tabs-activated-fg);
}

.Notifications {
	bottom: 40px;
}



.Tab[data-updated="true"][data-pin="true"] .fav-icon{
	mask: none;
}



/*pin color border*/
.Tab[data-pin="true"][data-active="true"] .body,
.Tab[data-active="true"] .color-layer {
  background-color: light-dark(rgba(255, 255, 255), var(--tabs-activated-bg));
}

.Tab[data-pin="false"][data-active="true"] .body {
	box-shadow:  0 1px 4px -1px rgba(0,0,0,0.322), inset 0 0 0 1px var(--s-act-el-border, light-dark(rgba(255,255,255,0.133),rgba(255,255,255,0.03)));;
}

.Tab[data-active="true"] .color-layer {
	box-shadow: inset 0 0 0 2.5px var(--tab-color);
}

.Tab[data-active="false"] .color-layer,
.Tab[data-pin="false"] .color-layer {
  display: none;
}
/* end */


.Notifications .notification{
  box-shadow: 0 1px 4px -1px rgba(0,0,0,0.322), inset 0 0 0 1px var(--s-act-el-border, rgba(255,255,255,0.133));
  &:hover{
      box-shadow: 0 1px 4px -1px rgba(0,0,0,0.322), inset 0 0 0 1px var(--s-act-el-border, rgba(255,255,255,0.133));
  }
}


.Tab:active .body::before {
	transition: background 0.15s linear !important;
}

.Tab[data-pin="false"] .ctx {
  left: 0 !important;
}


/*popup styling*/
.popup{
margin: 1px 7px;
border-radius: 6px;
background-color: var(--bgnotif);
border: 1px solid light-dark(rgba(50, 50, 50, 0.1), rgba(255, 255, 255, 0.1));
box-shadow: none;
}

.popup h2{
padding: 6px 4px 2px;
font-size: 1.025rem;
}

.Confirm .msg {
  font-size: 0.8rem;
}

.btn{
border-radius: 4px;
}

.btn.-warn::after, .btn::before {
border-radius:4px;
}

/*nav padd*/
.NavigationBar.-top {
  padding: var(--nav-btn-margin) 25px;
}
/*margin top nav*/
.top-horizontal-box {
  margin-top: 7px;
}

/*bookmark*/

.BookmarkNode[data-expanded="true"] > .body::before {
  background-color: var(--tabs-activated-bg);
  box-shadow: 0 1px 4px -1px rgba(0,0,0,0.322), inset 0 0 0 1px var(--s-act-el-border, light-dark(rgba(255,255,255,0.133),rgba(255,255,255,0.03)));
}

.BookmarkNode > .body:hover::before {
  background-color: var(--frame-el-overlay-hover-bg);
}


.Tab[data-active="true"]:hover .body::before {
  background-color: initial;
}

.BookmarkNode[data-expanded="true"] > .body:hover::before{
	background-color: var(--tabs-activated-bg);
	opacity: 0.7;
}

.BookmarkNode[data-open="true"] > .body::after{
display:none;
}


#root[data-pinned-tabs-position="top"] .Tab[data-pin="true"][data-loading="true"] .ctx {
  left: initial ;
}

#root[data-pinned-tabs-position="top"] .Tab[data-pin="true"] .ctx{
	left:initial ;
}


.Notifications .notification{
	background: var(--bgnotif);

border: 1px solid light-dark(rgba(50, 50, 50, 0.1), rgba(255, 255, 255, 0.1));
}





